mapper.select:
SELECT SAR.* FROM SMT_ARTICLES_RELEASE SAR LEFT JOIN SMT_PROCESS_RECORD SPR ON SAR.PROCESS_ID = SPR.PROCESS_ID WHERE SAR.ARTICLES_TYPE = 5
AND (SPR.STATUS = '0' OR SPR.STATUS = 'e')
AND SAR.PARK_ID IN
#{id}
AND (SPR.STATUS = '0' OR SPR.STATUS = 'e') AND SAR.SECURITY_STAFF = #{approveBadge}
AND (SELECT COUNT(SART.ID) FROM SMT_ARTICLES_RELEASE_THING SART WHERE SART.RELEASE_ID = SAR.ID AND SART.CPH = #{query.licensePlate}) > 0
AND (SAR.CARRIER LIKE CONCAT('%', CONCAT(#{query.name}, '%')) OR SAR.NAME LIKE CONCAT('%', CONCAT(#{query.name}, '%')))
AND SAR.BADGE = #{query.badge}
AND SAR.CREATE_TIME BETWEEN to_date(#{query.startTime},'yyyy-mm-dd hh24:mi:ss') AND to_date(#{query.endTime},'yyyy-mm-dd hh24:mi:ss')
ORDER BY SAR.CREATE_TIME DESC
